#!/usr/bin/env node
// Generates the matching tables for BOTH implementations (Dart app and the
// Cloudflare Worker) from shared/match_data.json, so they can never drift.
//
//   node tool/gen-match-data.mjs          # rewrite the generated files
//   node tool/gen-match-data.mjs --check  # exit 1 when they are out of date
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const data = JSON.parse(readFileSync(join(root, 'shared/match_data.json'), 'utf8'));
const check = process.argv.includes('--check');

const dq = (s) => JSON.stringify(s); // JSON strings are valid Dart strings (no $ in our data)
for (const k of Object.keys(data.synonyms)) {
  for (const a of data.synonyms[k]) if (a.includes('$')) throw new Error(`"$" not allowed: ${a}`);
}

// alias -> canonical
const aliasToCanon = {};
for (const [canon, aliases] of Object.entries(data.synonyms)) {
  aliasToCanon[canon] = canon;
  for (const a of aliases) aliasToCanon[a.toLowerCase()] = canon;
}

const header = '// GENERATED by tool/gen-match-data.mjs from shared/match_data.json - do not edit.\n';

const mjs = `${header}export const MATCH_DATA = ${JSON.stringify(
  { ...data, aliasToCanon, _comment: undefined },
  null,
  1,
)};\n`;

const dartList = (arr) => `[${arr.map(dq).join(', ')}]`;
const dart = `${header}// ignore_for_file: prefer_single_quotes, lines_longer_than_80_chars
part of 'match_engine.dart';

class MatchData {
  MatchData._();

  static const int threshold = ${data.threshold};
  static const double aiBlend = ${data.aiBlend};
  static const int aiMinRuleScore = ${data.aiMinRuleScore};
  static const int maxNotificationsPerItem = ${data.maxNotificationsPerItem};

  static const double wTitle = ${data.weights.title};
  static const double wDescription = ${data.weights.description};
  static const double wCategory = ${data.weights.category};
  static const double wLocation = ${data.weights.location};
  static const double wDate = ${data.weights.date};

  static const double tokenGeneric = ${data.tokenWeights.generic};
  static const double tokenColor = ${data.tokenWeights.color};
  static const double tokenNumber = ${data.tokenWeights.number};
  static const double tokenDefault = ${data.tokenWeights.default};

  static const Set<String> stopwords = {${data.stopwords.map(dq).join(', ')}};
  static const List<String> koreanSuffixes = ${dartList(data.koreanSuffixes)};
  static const List<List<String>> relatedCategories = [${data.relatedCategories
    .map(dartList)
    .join(', ')}];
  static const Set<String> colors = {${data.colors.map(dq).join(', ')}};
  static const Set<String> generic = {${data.generic.map(dq).join(', ')}};
  static const Map<String, String> aliasToCanon = {
${Object.entries(aliasToCanon)
  .map(([a, c]) => `    ${dq(a)}: ${dq(c)},`)
  .join('\n')}
  };
  static const Map<String, List<String>> expansions = {
${Object.entries(data.expansions)
  .map(([k, v]) => `    ${dq(k)}: ${dartList(v)},`)
  .join('\n')}
  };
}
`;

const targets = [
  [join(root, 'server/match_data.mjs'), mjs],
  [join(root, 'lib/matching/match_data.g.dart'), dart],
];
let stale = false;
for (const [file, text] of targets) {
  const same = existsSync(file) && readFileSync(file, 'utf8') === text;
  if (check) {
    if (!same) {
      console.error(`out of date: ${file}`);
      stale = true;
    }
  } else if (!same) {
    writeFileSync(file, text);
    console.log(`wrote ${file}`);
  }
}
if (check && stale) process.exit(1);
